pub fn any<T: Arbitrary>() -> T {
            T::any()
        }

fn any_raw<T: Copy>() -> T {
            kani_intrinsic()
        }

unsafe fn any_raw_internal<T: Copy>() -> T {
            any_raw::<T>()
        }

pub const fn assert(cond: bool, msg: &'static str) {
            let _ = cond;
            let _ = msg;
        }

fn kani_intrinsic<T>() -> T {
            #[allow(clippy::empty_loop)]
            loop {}
        }
